import json,re
from datetime import datetime
from collections import Counter,defaultdict
rows=[json.loads(l) for l in open('commits.jsonl',encoding='utf-8') if l.strip()]
HDR=re.compile(r'^([a-z]+)(?:\(([^()\s]+)\))?(!)?: (\S.*)$')
REV=re.compile(r'^This reverts commit ([0-9a-f]{40})\.$')
named=set()
for r in rows:
    for line in r['message'].splitlines():
        m=REV.match(line)
        if m: named.add(m.group(1))
mailmap={}
for line in open('.mailmap',encoding='utf-8'):
    line=line.strip()
    if not line or line.startswith('#'): continue
    m=re.match(r'^(.+?) <([^>]+)>(?: <([^>]+)>)?$',line)
    mailmap[m.group(2)]=m.group(1)
    if m.group(3): mailmap[m.group(3)]=m.group(1)
def cname(n,e): return mailmap.get(e,n)
inc=[]
for r in rows:
    h=r['message'].splitlines()[0]
    if h.startswith('Revert "') or r['hash'] in named: continue
    m=HDR.match(h)
    if not m: continue
    typ,scope,bang,summ=m.groups(); breaking=bool(bang)
    if not breaking and typ not in ('feat','fix','perf'): continue
    if scope=='internal' and not breaking: continue
    inc.append(r)
print("included commits:",len(inc))
cred=defaultdict(list)
for r in inc:
    a=cname(r['author'],r['email'])
    people=[a]
    for line in r['message'].splitlines():
        m=re.match(r'^Co-authored-by:\s*(.*?)\s*<([^>]*)>?\s*$',line)
        if m:
            co=cname(m.group(1),m.group(2))
            if co not in people: people.append(co)
    for p in people: cred[p].append(r['hash'][:7])
botnames={p for p in cred if p.endswith('[bot]')}
authored={cname(r['author'],r['email']) for r in inc}
for p in sorted(cred,key=lambda p:(-len(cred[p]),p)):
    if p.endswith('[bot]'): continue
    print(f"{p:18} total={len(cred[p]):2} authored_in_notes={p in authored}", cred[p])
print("bot credits:",{b:len(cred[b]) for b in botnames})
EOF

